.fmm-root [data-name="Symbol/SPST (Horizontal) Wrap"] > * > [data-name="Glyph"] > [data-name="Glyph"]{transform-origin:0 0;transform:translate(0,15px) rotate(-90deg)}
.fmm-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.fmm-root[data-theme="dark"] [data-name="Button/Ack (Hover)"] p{color:var(--wa-text, #0e1a2c)!important}
.fmm-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="logo chip"] img{filter:brightness(0) invert(1)!important}
.fmm-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="WEMB Studio"]{color:var(--wa-text, #fff)!important}
.fmm-root[data-theme="dark"] :is([data-name="Side Panel (Left)"],[data-name="Side Panel (Right)"]) > [data-name="Panel Body"]{box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),0 10px 30px rgba(0,0,0,.45)!important}
.fmm-root[data-theme="dark"] :is([data-name="Widget/Weather"] > [data-name="Row"],[data-name="Widget/Alarm Event"] > [data-name="Button Group"],[data-name="Widget/Mini Map"] > [data-name="Body"],[data-name="Widget/Plant Generation"] > [data-name="Body"],[data-name="Widget/Weekly Solar Generation"] > [data-name="Body"]){background:var(--wa-surface, #1f252e)!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),inset 0 1px 0 rgba(255,255,255,.05),0 6px 16px rgba(0,0,0,.35)!important}
.fmm-root[data-theme="dark"] :is([data-name="Widget/Alarm Event"],[data-name="Widget/Mini Map"]) > [data-name="Header"],.fmm-root[data-theme="dark"] :is([data-name="Widget/Plant Generation"],[data-name="Widget/Weekly Solar Generation"]) > [data-name="Body"] > [data-name="Header"]{background:linear-gradient(to top,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf))!important;box-shadow:0 4px 12px rgba(31,95,207,.35),inset 0 1px 0 rgba(255,255,255,.18)!important}
.fmm-root[data-theme="dark"] :is([data-name="Button/Solar"],[data-name="Button/Power Equipment"]) > [data-name="Body"] > [data-name="Background"]{background:linear-gradient(to right,color-mix(in srgb, var(--wa-point, rgb(59 130 234)) 55%, transparent) 28%,var(--wa-point, #2466d6) 62%)!important}
.fmm-root[data-theme="dark"] [data-name="Key Background"]{background:linear-gradient(to left,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf) 53%)!important}
.fmm-root[data-theme="dark"] [data-name^="Item/"] [data-name="Value"]{color:var(--wa-text, #f1f3f8)!important}
.fmm-root[data-theme="dark"] [data-name^="Direction/"] p,.fmm-root[data-theme="dark"] p[data-name^="Direction/"]{color:var(--wa-point, #1d2747)!important}
.fmm-root[data-theme="dark"] [data-name^="Meter Card/"] [data-name="Title"]{color:var(--wa-text, #0f1420)!important;font-weight:600}
.fmm-root[data-theme="dark"] [data-name="Badge/Critical"] p{color:var(--wa-danger, #ff5a57)!important}
.fmm-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"]){background:var(--wa-surface, #232a35)!important}
.fmm-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"])::after{border-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 12%, transparent)!important}
.fmm-root[data-theme="dark"] .nI2141_760_2126_787{background-color:var(--wa-surface, #161a21);box-shadow:1px 1px 1px 0px rgba(0,0,0,0.4)}
